###############################################################################
##
##  06_00_common.R
##
##  Directories, figure geometry and style as well as 
##  LaTex output specifications for single values and entire tables. 
##
##  Every driver sets three names in its own configuration block, before it
##  writes anything:
##     SRC         its file name, printed in the stamp of every generated file
##     TEX_PREFIX  the prefix of the generated \newcommand names
##     TEX_SCI     TRUE prints a small scalar as a \cdot 10^{b}, FALSE as a decimal
##
##  theme_thesis() needs ggplot2, which is attached by the drivers that plot.
##
###############################################################################


## ---------------------------------------------------------------------------
## Directories
## ---------------------------------------------------------------------------

INPUT_DIR  <- "data"    # the two CSV input files with the DAV data
OUTPUT_DIR <- "output"  # working files, not included in the thesis
FIG_DIR    <- "figures" # PDF figures, included with \includegraphics
TAB_DIR    <- "tables"  # LaTeX fragments for tables and values, included with \input


## ---------------------------------------------------------------------------
## Figure geometry and colours (mostly taken from TUM Corporate Design)
## ---------------------------------------------------------------------------

FIG_WIDTH_IN  <- 6.00
FIG_HEIGHT_IN <- 2.60        # three panels plus the legend strip
FIG_POINTSIZE <- 10
FIG_FAMILY    <- "Times"     # base-14 PDF font, nothing to embed

## General colours for the figures
COL_FIT   <- "#9ABCE4"
COL_TABLE <- "#0E396E"
COL_GRID  <- "#E5E5E5"
COL_STRIP <- "#E5E5E5"
COL_LINE  <- "#999999"       # panel border and ticks
COL_LINE_D<- "gray25"        # darker gray for the VaR and ES lines
COL_HEAD  <- "black"
COL_ALT      <- "#C7D97D"
COL_ALT_DARK <- "#7D922A"


## ---------------------------------------------------------------------------
## LaTeX output functions
## ---------------------------------------------------------------------------

## Headline for automatically generated .tex files
tex_stamp <- function(src = SRC)
  c(paste0("% Generated by ", src, " -- do not edit by hand."),
    paste0("% ", format(Sys.time(), "%Y-%m-%d %H:%M:%S")))

## The main function to format and round desired number to amount of digits
tex_fixed <- function(v, digits) formatC(v, format = "f", digits = digits)

## Rounded upwards, so that a section can say "by less than ...".
tex_ceil <- function(v, digits) {
  s <- 10^digits
  tex_fixed(ceiling(abs(v) * s - 1e-9) / s, digits)
}

## Rounded downwards, so that a section can say "by at least ...".
tex_floor <- function(v, digits) {
  s <- 10^digits
  tex_fixed(floor(abs(v) * s - 1e-9) / s, digits)
}

## Scalar edge cases: fixed point within three orders of magnitude, scientific
## notation outside and for values with |v| < 10^-3 or |v| > 10^3.  
## With TEX_SCI = FALSE the second branch is skipped and
## everything is printed as a decimal.
tex_scalar <- function(v, digits = 2, sci = TEX_SCI) {
  if (!is.finite(v)) return("\\mathrm{NA}")
  if (v == 0) return("0")
  e <- floor(log10(abs(v)))
  if (!sci || (e >= -3L && e <= 3L))
    return(tex_fixed(v, min(6L, max(0L, digits - e))))
  sprintf("%s \\cdot 10^{%d}", tex_fixed(v / 10^e, digits), as.integer(e))
}

## One \newcommand per scalar.  The caller passes name without
## digits or underscores, TEX_PREFIX keeps it apart from the hand-written ones.
tex_macro <- function(name, body) {
  full <- paste0(TEX_PREFIX, name)
  if (grepl("[^A-Za-z]", full))
    stop("the macro name ", full, " contains a character LaTeX does not accept")
  sprintf("\\newcommand{\\%s}{%s}", full, body)
}

## Final function to actually write the .tex file with header and content
write_tex_macros <- function(lines, path) {
  writeLines(c(tex_stamp(),
               paste0("% Macros holding a number are math material; use them as $\\",
                      TEX_PREFIX, "...$."),
               "", lines), path)
  path
}

## Complete and flexible function to write a insert-ready table in latex format
##    df contains the actual data
##    headers contains the header names of the dataframe
##    digits contains numbers or NA for each column on how to round it
##    align defines the alignments for the columns
##    above can additionaly insert extra-headers
write_tex_tabular <- function(df, headers, digits, path,
                              align = paste(rep("r", ncol(df)), collapse = ""),
                              above = NULL) {
  stopifnot(ncol(df) == length(headers), ncol(df) == length(digits))
  ## Content of the table written row-wise into body
  body <- character(nrow(df))
  for (i in seq_len(nrow(df))) {
    ## Extract the values of this i-th row for every column into cells
    cells <- character(ncol(df))
    for (j in seq_len(ncol(df))) {
      v <- df[[j]][i]
      ## Write the value directly or format it accordingly
      if (is.na(digits[j])) {
        cells[j] <- as.character(v)
      } else {
        cells[j] <- paste0("$", tex_fixed(v, digits[j]), "$")
      }
    }
    body[i] <- paste0("    ", paste(cells, collapse = " & "), " \\\\")
  }
  ## Put everything together
  writeLines(c(tex_stamp(),
               paste0("\\begin{tabular}{", align, "}"),
               "    \\toprule",
               above,
               paste0("    ", paste(headers, collapse = " & "), " \\\\"),
               "    \\midrule",
               body,
               "    \\bottomrule",
               "\\end{tabular}"), path)
  path
}


## ---------------------------------------------------------------------------
## Figure helpers
## ---------------------------------------------------------------------------

## PDF device sized for \includegraphics[width=\textwidth] without rescaling.
## Times is a base-14 PDF font, so nothing has to be embedded.
open_tex_figure <- function(file, width = FIG_WIDTH_IN, height = FIG_HEIGHT_IN) {
  pdf(file.path(FIG_DIR, file), width = width, height = height,
      pointsize = FIG_POINTSIZE, family = FIG_FAMILY)
  invisible(file.path(FIG_DIR, file))
}

## Plain theme for the thesis figures: 
## light grid, thin frame, no colour beyond the colours of the data.
theme_thesis <- function(base_size = FIG_POINTSIZE, base_family = FIG_FAMILY) {
  theme_bw(base_size = base_size, base_family = base_family) +
    theme(panel.border     = element_rect(colour = COL_LINE, linewidth = 0.3),
          panel.grid.major = element_line(colour = COL_GRID, linewidth = 0.3),
          panel.grid.minor = element_blank(),
          axis.ticks       = element_line(colour = COL_LINE, linewidth = 0.3),
          axis.title       = element_text(size = rel(0.95)),
          strip.background = element_rect(fill = COL_STRIP, colour = COL_LINE,
                                          linewidth = 0.3),
          strip.text       = element_text(colour = COL_HEAD, size = rel(0.95),
                                          margin = margin(3, 3, 3, 3)),
          legend.position  = "bottom",
          legend.title     = element_blank(),
          legend.margin    = margin(t = -4),
          legend.text      = element_text(size = rel(0.9)),
          plot.margin      = margin(4, 6, 2, 2))
}
